debug.error_function_source:
async def act(page):
    """
    From the current Manage Products listing, add two new simple products for Nona Fitness Tank:
    - Nona Fitness Tank-XXS-Blue
    - Nona Fitness Tank-XXS-Purple

    Strategy:
    1. Click the Add Product . . . button (use the precise accessibility path shown in the tree).
    2. On the product create page, fill required fields (Name, SKU, Price, Qty) and set Color and Size.
       Attempt to set Size via combobox; try several fallbacks if the exact control naming differs.
    3. Save the product.
    4. Attempt to use a duplication flow (Save and Duplicate or Duplicate) to quickly create the Purple variant
       from the Blue product. If duplication controls are not present, fall back to returning to the Manage Products
       grid and creating the Purple product via the Add Product flow again.

    Notes about knowledge-base helper functions: there are none available, so this uses Playwright accessibility-based
    APIs (.get_by_role, .select_option, .fill, .click) exclusively.
    """

    # 1) Click Add Product . . . via the exact table/row/cell/button path from the accessibility tree
    try:
        await page.get_by_role("table").get_by_role("row", name="Manage Products Add Product . . .").get_by_role("button", name="Add Product . . .").click()
    except Exception:
        # If the exact path fails, try a reasonable fallback to click any top-level "Add Product" button
        try:
            await page.get_by_role("button", name="Add Product . . .").click()
        except Exception:
            # Cannot proceed without opening the Add Product page
            return

    # Wait for the product create/edit page to load; wait for a common control like the Name textbox
    for _ in range(10):
        try:
            await page.get_by_role("textbox", name="Name").wait_for(state="visible", timeout=500)
            break
        except Exception:
            await page.wait_for_timeout(300)

    async def create_simple_product(color: str, sku_suffix: str):
        """Fill the product form for a simple Nona Fitness Tank of size XXS and given color, then save.
        Returns True on success.
        """
        # Fill Name
        try:
            await page.get_by_role("textbox", name="Name").fill(f"Nona Fitness Tank-XXS-{color}")
        except Exception:
            # fallback: first textbox may be the name
            try:
                await page.get_by_role("textbox").nth(0).fill(f"Nona Fitness Tank-XXS-{color}")
            except Exception:
                return False

        # Fill SKU if available
        sku_val = f"WT04-XXS-{color}"
        try:
            await page.get_by_role("textbox", name="SKU").fill(sku_val)
        except Exception:
            # try typical second textbox position if labeling varies
            try:
                await page.get_by_role("textbox").filter(has_text="SKU").fill(sku_val)
            except Exception:
                pass

        # Fill Price if present
        try:
            await page.get_by_role("textbox", name="Price").fill("39")
        except Exception:
            try:
                # sometimes price label is "Price" but role may still be textbox nth
                await page.get_by_role("textbox").filter(has_text="Price").fill("39")
            except Exception:
                pass

        # Fill Qty if present
        try:
            await page.get_by_role("textbox", name="Qty").fill("100")
        except Exception:
            try:
                await page.get_by_role("textbox").filter(has_text="Qty").fill("100")
            except Exception:
                pass

        # Set Status to Enabled if possible
        try:
            await page.get_by_role("combobox", name="Status").select_option(option_name="Enabled")
        except Exception:
            pass

        # Set Visibility to Catalog, Search if available
        try:
            await page.get_by_role("combobox", name="Visibility").select_option(option_name="Catalog, Search")
        except Exception:
            pass

        # Set Color attribute
        try:
            await page.get_by_role("combobox", name="Color").select_option(option_name=color)
        except Exception:
            # fallback: try combobox by role with nth or a textbox
            try:
                await page.get_by_role("combobox").filter(has_text="Color").select_option(option_name=color)
            except Exception:
                try:
                    await page.get_by_role("textbox", name="Color").fill(color)
                except Exception:
                    pass

        # Set Size attribute to XXS. Try several selection methods.
        size_set = False
        try:
            await page.get_by_role("combobox", name="Size").select_option(option_name="XXS")
            size_set = True
        except Exception:
            try:
                # try by value in case option_name labeling differs
                await page.get_by_role("combobox", name="Size").select_option(value="XXS")
                size_set = True
            except Exception:
                try:
                    # fallback: any combobox containing 'Size' in a label
                    await page.get_by_role("combobox").filter(has_text="Size").select_option(option_name="XXS")
                    size_set = True
                except Exception:
                    try:
                        await page.get_by_role("textbox", name="Size").fill("XXS")
                        size_set = True
                    except Exception:
                        size_set = False

        # Final save of this new simple product
        await page.wait_for_timeout(400)
        # Try Save first
        try:
            await page.get_by_role("button", name="Save").click()
        except Exception:
            # try Save and Continue Edit as a fallback
            try:
                await page.get_by_role("button", name="Save and Continue Edit").click()
            except Exception:
                # if no save buttons found, abort
                return False

        # wait a bit for save to complete
        await page.wait_for_timeout(1200)
        return True

    # 2) Create Blue product
    created_blue = await create_simple_product("Blue", "XXS-Blue")

    # 3) Try to duplicate the Blue product to make Purple
    did_duplicate_and_save = False
    if created_blue:
        # Attempt to find and click a duplication action
        try:
            # Try a direct 'Save and Duplicate' button (some installs have it)
            await page.get_by_role("button", name="Save and Duplicate").click()
            # Wait for duplicated form to appear then change color to Purple and SKU
            await page.wait_for_timeout(600)
            try:
                await page.get_by_role("combobox", name="Color").select_option(option_name="Purple")
            except Exception:
                try:
                    await page.get_by_role("textbox", name="Color").fill("Purple")
                except Exception:
                    pass
            try:
                await page.get_by_role("textbox", name="SKU").fill("WT04-XXS-Purple")
            except Exception:
                pass
            # Save duplicated product
            try:
                await page.get_by_role("button", name="Save").click()
                did_duplicate_and_save = True
                await page.wait_for_timeout(1000)
            except Exception:
                pass
        except Exception:
            # No Save and Duplicate button found; try a Duplicate button or link
            try:
                await page.get_by_role("button", name="Duplicate").click()
                await page.wait_for_timeout(600)
                try:
                    await page.get_by_role("combobox", name="Color").select_option(option_name="Purple")
                except Exception:
                    try:
                        await page.get_by_role("textbox", name="Color").fill("Purple")
                    except Exception:
                        pass
                try:
                    await page.get_by_role("textbox", name="SKU").fill("WT04-XXS-Purple")
                except Exception:
                    pass
                try:
                    await page.get_by_role("button", name="Save").click()
                    did_duplicate_and_save = True
                    await page.wait_for_timeout(1000)
                except Exception:
                    pass
            except Exception:
                # Try a link named Duplicate
                try:
                    await page.get_by_role("link", name="Duplicate").click()
                    await page.wait_for_timeout(600)
                    try:
                        await page.get_by_role("combobox", name="Color").select_option(option_name="Purple")
                    except Exception:
                        try:
                            await page.get_by_role("textbox", name="Color").fill("Purple")
                        except Exception:
                            pass
                    try:
                        await page.get_by_role("textbox", name="SKU").fill("WT04-XXS-Purple")
                    except Exception:
                        pass
                    try:
                        await page.get_by_role("button", name="Save").click()
                        did_duplicate_and_save = True
                        await page.wait_for_timeout(1000)
                    except Exception:
                        pass
                except Exception:
                    did_duplicate_and_save = False

    # 4) If duplication didn't work, go back to Manage Products and create Purple via Add Product flow
    if not did_duplicate_and_save:
        try:
            # Navigate back to Manage Products listing
            await page.goto("/index.php/admin/catalog_product/index/")
            # Wait for listing to load
            await page.wait_for_timeout(800)
            # Click Add Product again
            try:
                await page.get_by_role("table").get_by_role("row", name="Manage Products Add Product . . .").get_by_role("button", name="Add Product . . .").click()
            except Exception:
                try:
                    await page.get_by_role("button", name="Add Product . . .").click()
                except Exception:
                    return
            # Wait for the add form
            for _ in range(10):
                try:
                    await page.get_by_role("textbox", name="Name").wait_for(state="visible", timeout=500)
                    break
                except Exception:
                    await page.wait_for_timeout(300)
            # Create Purple product
            await create_simple_product("Purple", "XXS-Purple")
        except Exception:
            # If any of this fails, end gracefully
            return

    # 5) After creating both, attempt a final Save if on a product edit page to ensure persistence
    try:
        await page.get_by_role("button", name="Save").click()
    except Exception:
        pass

    # Allow final UI updates
    await page.wait_for_timeout(800)

    return

