                try:
                    await page.get_by_role("textbox", name="Color").fill("Purple")
                except Exception:
                    pass
            try:
                await page.get_by_role("textbox", name="SKU").fill("WT04-XXS-Purple")
            except Exception:
                pass
            # Save duplicated product
            try:
                await page.get_by_role("button", name="Save").click()
                did_duplicate_and_save = True
                await page.wait_for_timeout(1000)
            except Exception:
                pass
        except Exception:
            # No Save and Duplicate button found; try a Duplicate button or link
            try:
                await page.get_by_role("button", name="Duplicate").click()
                await page.wait_for_timeout(600)
                try:
                    await page.get_by_role("combobox", name="Color").select_option(option_name="Purple")
                except Exception:
                    try:
                        await page.get_by_role("textbox", name="Color").fill("Purple")
                    except Exception:
                        pass
                try:
                    await page.get_by_role("textbox", name="SKU").fill("WT04-XXS-Purple")
                except Exception:
                    pass
                try:
                    await page.get_by_role("button", name="Save").click()
                    did_duplicate_and_save = True
                    await page.wait_for_timeout(1000)
                except Exception:
                    pass
            except Exception:
                # Try a link named Duplicate
                try:
                    await page.get_by_role("link", name="Duplicate").click()
                    await page.wait_for_timeout(600)
                    try:
                        await page.get_by_role("combobox", name="Color").select_option(option_name="Purple")
                    except Exception:
                        try:
                            await page.get_by_role("textbox", name="Color").fill("Purple")
                        except Exception:
                            pass
                    try:
                        await page.get_by_role("textbox", name="SKU").fill("WT04-XXS-Purple")
                    except Exception:
                        pass
                    try:
                        await page.get_by_role("button", name="Save").click()
                        did_duplicate_and_save = True
                        await page.wait_for_timeout(1000)
                    except Exception:
                        pass
                except Exception:
                    did_duplicate_and_save = False

    # 4) If duplication didn't work, go back to Manage Products and create Purple via Add Product flow
    if not did_duplicate_and_save:
        try:
            # Navigate back to Manage Products listing
            await page.goto("/index.php/admin/catalog_product/index/")
            # Wait for listing to load
            await page.wait_for_timeout(800)
            # Click Add Product again
            try:
                await page.get_by_role("table").get_by_role("row", name="Manage Products Add Product . . .").get_by_role("button", name="Add Product . . .").click()
            except Exception:
                try:
                    await page.get_by_role("button", name="Add Product . . .").click()
                except Exception:
                    return
            # Wait for the add form
            for _ in range(10):
                try:
                    await page.get_by_role("textbox", name="Name").wait_for(state="visible", timeout=500)
                    break
                except Exception:
                    await page.wait_for_timeout(300)
            # Create Purple product
            await create_simple_product("Purple", "XXS-Purple")
        except Exception:
            # If any of this fails, end gracefully
            return

    # 5) After creating both, attempt a final Save if on a product edit page to ensure persistence
    try:
        await page.get_by_role("button", name="Save").click()
    except Exception:
        pass

    # Allow final UI updates
    await page.wait_for_timeout(800)

    return
